$st = ['pending' => ['secondary', 'لم يُسدَّد'], 'partial' => ['warning', 'جزئي'], 'paid' => ['success', 'مسدّد']]; ?>
<div class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="h5 mb-0"><a href="<?= url('school/students/' . (int)$f['student_id']) ?>"><?= e($f['full_name']) ?></a></h2><span class="text-muted"><?= e($f['grade_name'] . ' / ' . $f['section_name']) ?> — <?= e($f['structure_name']) ?></span>
