<div class="row g-3 mb-3"><?php foreach ([['المستحق', $f['payable'], ''], ['المدفوع', $f['paid'], 'text-success'], ['المتبقي', $f['balance'], $bal > 0 ? 'text-danger' : 'text-success']] as [$l, $v, $c]): ?><div class="col-4"><div class="card-s text-center"><div class="fs-4 fw-bold <?= $c ?>"><?= number_format((float)$v, 2) ?></div><div class="small text-muted"><?= $l ?> (<?= e($cur) ?>)</div></div></div><?php endforeach; ?></div>
<div class="row g-3">
  <div class="col-lg-7">
