      <?php if ((float)$f['discount_total'] > 0): ?><tr class="text-success"><td>خصم<?= $f['discount_reason'] ? ': ' . e($f['discount_reason']) : '' ?></td><td class="text-end">-<?= number_format((float)$f['discount_total'], 2) ?></td></tr><?php endif; ?>
      <?php if ((float)$f['tax_amount'] > 0): ?><tr><td>ضريبة <?= e($f['tax_percent']) ?>%</td><td class="text-end"><?= number_format((float)$f['tax_amount'], 2) ?></td></tr><?php endif; ?>
      <tr class="fw-bold"><td>الصافي المستحق</td><td class="text-end"><?= number_format((float)$f['payable'], 2) ?> <?= e($cur) ?></td></tr></tbody></table></div>
    <div class="card-s mb-3"><h3 class="h6">الأقساط</h3><div class="table-responsive"><table class="table table-sm align-middle table-cards mb-0"><thead><tr><th>#</th><th>الاستحقاق</th><th>القيمة</th><th>المسدَّد</th><th>الحالة</th></tr></thead><tbody>
      <?php foreach ($f['installments'] as $i): $late = $i['status'] !== 'paid' && $i['due_date'] < date('Y-m-d'); ?><tr class="<?= $late ? 'table-danger' : '' ?>"><td data-label="#"><?= (int)$i['seq'] ?></td><td data-label="الاستحقاق" dir="ltr"><?= e($i['due_date']) ?><?= $late ? ' <span class="badge text-bg-danger">متأخر</span>' : '' ?></td><td data-label="القيمة"><?= number_format((float)$i['amount'], 2) ?></td><td data-label="المسدَّد"><?= number_format((float)$i['paid_amount'], 2) ?></td><td data-label="الحالة"><span class="badge text-bg-<?= $st[$i['status']][0] ?>"><?= $st[$i['status']][1] ?></span></td></tr><?php endforeach; ?></tbody></table></div></div>
    <div class="card-s"><h3 class="h6">الدفعات والسندات</h3><?php if (!$f['payments']): ?><div class="empty-state">لا توجد دفعات.</div><?php else: ?><div class="table-responsive"><table class="table table-sm align-middle table-cards mb-0"><thead><tr><th>السند</th><th>التاريخ</th><th>المبلغ</th><th>الطريقة</th><th>المرجع</th><th></th></tr></thead><tbody>
      <?php foreach ($f['payments'] as $p): $v = (bool)$p['voided_at']; ?><tr class="<?= $v ? 'text-decoration-line-through text-muted' : '' ?>"><td data-label="السند"><a target="_blank" href="<?= url('school/fees/receipts/' . (int)$p['receipt_id'] . '/print') ?>"><?= e($p['receipt_no']) ?></a><?= $v ? ' <span class="badge text-bg-danger">ملغى</span>' : '' ?></td><td data-label="التاريخ" dir="ltr"><?= e($p['paid_on']) ?></td>
        <td data-label="المبلغ"><?= number_format((float)$p['amount'], 2) ?> <?= e($p['currency']) ?><?php if ($p['currency'] !== $cur && (float)$p['applied_amount'] > 0): $per = (float)$p['amount'] / (float)$p['applied_amount']; ?><br><small class="text-muted">= <?= number_format((float)$p['applied_amount'], 2) ?> <?= e($cur) ?> (<?= $per >= 1 ? '1 ' . e($cur) . ' = ' . round($per, 4) . ' ' . e($p['currency']) : '1 ' . e($p['currency']) . ' = ' . round(1 / $per, 4) . ' ' . e($cur) ?>)</small><?php endif; ?></td><td data-label="الطريقة"><?= e($p['method_name']) ?></td><td data-label="المرجع"><?= e($p['reference_no']) ?></td>
        <td><?php if (!$v && $canV): ?><button class="btn btn-sm btn-outline-danger" data-api="<?= url('api/v1/school/fees/payments/' . (int)$p['id'] . '/void') ?>" data-prompt="سبب إلغاء الدفعة (يُسجَّل، ويبقى السند ظاهرًا كملغى):">إلغاء</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
  </div>
  <div class="col-lg-5">
