        <div class="col-12 d-none" id="rateRow"><label class="form-label" for="rate">سعر الصرف (<span id="rateCur"></span> مقابل <?= e($base) ?>)</label><input class="form-control" id="rate" name="rate" type="number" step="0.000001" min="0"><div class="small text-muted" id="convInfo"></div></div>
