        <div class="col-7"><label class="form-label" for="reference_no">رقم المرجع <small class="text-muted" id="refHint"></small></label><input class="form-control" id="reference_no" name="reference_no" dir="ltr"></div>
        <div class="col-5"><label class="form-label" for="paid_on">التاريخ</label><input class="form-control" id="paid_on" name="paid_on" type="date" value="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d') ?>"></div></div>
      <button class="btn btn-success w-100 mt-3" type="submit"><i class="bi bi-cash"></i> تحصيل وإصدار سند</button><button type="button" class="btn btn-sm btn-link w-100" id="fillBal">المتبقي بالكامل (<?= number_format($bal, 2) ?> <?= e($cur) ?>)</button></form><?php endif; ?>
    <div class="card-s mb-3"><h3 class="h6">الفاتورة</h3>
      <?php if ($inv): ?><div>رقم <strong><?= e($inv['number']) ?></strong> <span class="badge text-bg-<?= ['issued' => 'secondary', 'partial' => 'warning', 'paid' => 'success'][$inv['status']] ?? 'secondary' ?>"><?= ['issued' => 'صادرة', 'partial' => 'مسدّدة جزئيًا', 'paid' => 'مسدّدة'][$inv['status']] ?? $inv['status'] ?></span></div>
        <div class="d-flex gap-2 mt-2"><a class="btn btn-sm btn-outline-primary" target="_blank" href="<?= url('school/fees/invoices/' . (int)$inv['id'] . '/print') ?>"><i class="bi bi-printer"></i> طباعة</a><?php if ($canV): ?><button class="btn btn-sm btn-outline-danger" data-api="<?= url('api/v1/school/fees/invoices/' . (int)$inv['id'] . '/cancel') ?>" data-prompt="سبب إلغاء الفاتورة:">إلغاء</button><?php endif; ?></div>
      <?php elseif ($canM && $f['status'] === 'active'): ?><p class="small text-muted">لم تُصدر فاتورة رسمية بعد.</p><button class="btn btn-outline-primary" data-api="<?= url("api/v1/school/fees/students/$fid/invoice") ?>" data-confirm="إصدار فاتورة رسمية مرقمة؟">إصدار فاتورة</button><?php endif; ?></div>
    <div class="card-s"><h3 class="h6">ولي الأمر</h3><?php foreach ($f['guardians'] as $g): ?><div><?= e($g['full_name']) ?> <small class="text-muted" dir="ltr"><?= e($g['phone']) ?></small><?= $g['financially_responsible'] ? ' <span class="badge text-bg-info">مسؤول مالي</span>' : '' ?></div><?php endforeach; ?><?php if (!$f['guardians']): ?><div class="text-muted small">لا يوجد ولي أمر مرتبط.</div><?php endif; ?>
      <?php if ($canM && $f['status'] === 'active'): ?><hr><button class="btn btn-sm btn-outline-danger" data-api="<?= url("api/v1/school/fees/students/$fid/cancel") ?>" data-prompt="سبب إلغاء الرسوم (لا يُسمح إن وُجدت دفعات):">إلغاء تعيين الرسوم</button><?php endif; ?></div>
